{
  "status": "SUPPORTED",
  "task_summary": "Find a compatible fastener, install it on the workbench, and store the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "A hardware piece (like a screw or bolt) that connects two items.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "washer"
        ],
        "required_properties": [
          "threaded",
          "metallic"
        ]
      },
      {
        "id": "workpiece",
        "entity_kind": "FIXED_TARGET",
        "function": "The object being secured or joined.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "bracket",
          "frame"
        ],
        "required_properties": [
          "has_hole",
          "needs_securing"
        ]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to apply the fastener (e.g., screwdriver).",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "hammer"
        ],
        "required_properties": [
          "gripping",
          "turning"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_with",
        "relation": "The fastening component must fit and secure the workpiece.",
        "participant_roles": [
          "fastening_component",
          "workpiece"
        ]
      ,
      "required": true
      },
      {
        "id": "driven_by",
        "relation": "The fastening tool is used to drive the fastening component.",
        "participant_roles": [
          "fastening_tool",
          "fastening_component"
        ]
      ,
      "required": true
      },
      {
        "id": "placed_on",
        "relation": "The fastening tool is left on the workbench after use.",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "retrieve_fastening_component",
        "operation": "Locate and pick up a compatible fastening component from storage or the table.",
        "participant_roles": [
          "fastening_component",
          "fastening_tool"
        ]
      ,
      "operation_count": 1
      },
      {
        "id": "install_fastening",
        "operation": "Insert and tighten the fastening component into the workpiece.",
        "participant_roles": [
          "fastening_component",
          "workpiece",
          "fastening_tool"
        ]
      ,
      "operation_count": 1
      },
      {
        "id": "store_tool",
        "operation": "Place the fastening tool onto the workbench surface.",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_component": [
        {
          "label": "yellow_object_on_table",
          "visual_description": "A yellow rectangular object sitting on a black tray on the table surface."
        }
      ],
      "workpiece": [
        {
          "label": "table",
          "visual_description": "The wooden workbench surface."
        }
      ],
      "fastening_tool": [
        {
          "label": "robot_arm",
          "visual_description": "The white robotic arm present in the scene."
        },
        {
          "label": "yellow_object_near_base",
          "visual_description": "A yellow blocky object visible near the robot base in the third view."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "Blue cabinet",
        "visual_description": "A tall blue cabinet against the wall with a closed door.",
        "reason": "Closed storage structure likely containing hardware components."
      },
      {
        "id": "drawers",
        "label": "Table drawers",
        "visual_description": "Two blue drawers under the table with handles visible.",
        "reason": "Closed storage structures likely containing small tools or fasteners."
      }
    ],
    "inspection_order": [
      "cabinet",
      "drawers",
      "table_surface"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
